import { Bot, BookOpen, CalendarClock, ChevronLeft, ChevronRight, ClipboardList, Clock3, FileCode2, FileText, FolderOpen, Gamepad2, Github, GitPullRequest, ImagePlus, Link2, ListTodo, Loader2, MessageSquarePlus, Mic, Monitor, Paperclip, Play, Plus, Presentation, ShieldCheck, Sparkles, Wand2, X } from "lucide-react";
