  const [selectedSessionId, setActiveSessionId] = useState<number | null>(() => { if (typeof window === "undefined") return null; const value = new URLSearchParams(window.location.search).get("session"); return value ? Number(value) : null; });
  const [newChatProjectId, setNewChatProjectId] = useState<number | null>(null);
  const [repositoryOpen, setRepositoryOpen] = useState(() => typeof window !== "undefined" && new URLSearchParams(window.location.search).get("repo") === "1");
